  const [isGeneratingImages, setIsGeneratingImages] = useState(false);
  const [canRegen, setCanRegen] = useState(true);
  const [showRegenModal, setShowRegenModal] = useState(false);
  const [regenInput, setRegenInput] = useState('');
  const [regenError, setRegenError] = useState('');

  const handleFileChange = async (selectedFile: File | null) => {
    if (!selectedFile) return;

    setError('');
    clearFile();

    try {
        const processed = await processAndValidateFile(selectedFile);
        setFile(processed.file);

        switch (processed.type) {
            case 'image':
                setLyrics(''); 
                setFilePreview(processed.previewUrl || null);
                break;
            case 'audio':
                setLyrics('');
                break;
            case 'text':
                setLyrics(processed.content);
                break;
        }
    } catch (err) {
        setError((err as Error).message);
        clearFile();
    }
  };

  const clearFile = () => {
    setFile(null);
    setFilePreview(null);
  }

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => e.preventDefault();
  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    handleFileChange(e.dataTransfer.files?.[0] ?? null);
  };

  const handleAnalyze = async () => {
    if (!lyrics && !file) {
      setError('Please provide lyrics or a file to analyze.');
      return;
    }
    setError('');
    setIsLoading(true);
    setAnalysis('');
    setGeneratedImages([]);
    setCanRegen(true);

    try {
        const result = await analyzeSong(title, artist, lyrics, concept, file, options);
        setAnalysis(result);

        if (options.generateArt) {
            setIsGeneratingImages(true);
            const images = await generateConceptImages(title, artist, concept, result);
            setGeneratedImages(images);
            setIsGeneratingImages(false);
        }
    } catch (e) {
        setError('Analysis failed. Please try again.');
    } finally {
        setIsLoading(false);
    }
  };

  const handleRegenSubmit = async () => {
    const words = regenInput.trim().split(/\s+/);
    if (words.length !== 2) {
        setRegenError('Please enter exactly 2 words.');
        return;
    }

    setShowRegenModal(false);
    setIsGeneratingImages(true);
    setCanRegen(false); // One-shot only

    // Use the existing analysis as context
    const images = await generateConceptImages(title, artist, concept, analysis, regenInput);
    setGeneratedImages(images);
    setIsGeneratingImages(false);
  };

  const isButtonDisabled = isLoading || (!lyrics && !file);
  const acceptedTypesString = Object.keys(ACCEPTED_FILE_TYPES).join(',');

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative">
      <div>
        <h2 className="text-2xl font-bold text-gray-100 mb-4">Song Input</h2>
        <div className="space-y-4">
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Song Title (Optional)"
            className="w-full bg-gray-900 border border-gray-600 rounded-md px-3 py-2 focus:ring-purple-500 focus:border-purple-500 transition"
          />
          <input
            type="text"
            value={artist}
            onChange={(e) => setArtist(e.target.value)}
            placeholder="Artist (Optional)"
            className="w-full bg-gray-900 border border-gray-600 rounded-md px-3 py-2 focus:ring-purple-500 focus:border-purple-500 transition"
          />

          <div 
            className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center cursor-pointer hover:border-purple-400 transition-colors bg-gray-900/50"
            onClick={() => document.getElementById('file-upload')?.click()}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
          >
            <input type="file" id="file-upload" className="hidden" onChange={(e) => handleFileChange(e.target.files?.[0] ?? null)} accept={acceptedTypesString}/>
            {file ? (
              <div className="flex flex-col items-center">
                {filePreview ? (
                    <img src={filePreview} alt="Preview" className="max-h-24 mx-auto mb-2 rounded border border-gray-700"/>
                ) : file.type.startsWith('audio/') ? (
                    <MusicNoteIcon className="w-16 h-16 text-gray-500 mb-2" />
                ) : null }
                <p className="text-gray-300 text-sm font-medium">{file.name}</p>
                <button onClick={(e) => { e.stopPropagation(); clearFile(); }} className="mt-1 text-xs text-red-400 hover:text-red-300">Remove</button>
              </div>
            ) : (
              <div className='flex flex-col items-center gap-2'>
                <UploadIcon className="w-8 h-8 text-gray-500"/>
                <p className="text-gray-400">Drag & drop or <span className="text-purple-400 font-semibold">browse</span></p>
                <p className="text-xs text-gray-500">.txt, .png, .jpg, .mp3, .wav, .m4a</p>
              </div>
            )}
          </div>

          <textarea
            value={lyrics}
            onChange={(e) => { 
              setLyrics(e.target.value); 
              if(file && file.type !== 'text/plain') clearFile(); 
            }}
            placeholder="Paste your lyrics here..."
            rows={6}
            className="w-full bg-gray-900 border border-gray-600 rounded-md px-3 py-2 focus:ring-purple-500 focus:border-purple-500 transition"
          />
          <textarea
